// ZwpTabletV2InterfaceName is the name of the interface as it appears in the [client.Registry].
// It can be used to match the [client.RegistryGlobalEvent.Interface] in the
// [Registry.SetGlobalHandler] and can be used in [Registry.Bind] if this applies.
const ZwpTabletV2InterfaceName = "zwp_tablet_v2"

// ZwpTabletV2 : graphics tablet device
//
// The wp_tablet interface represents one graphics tablet device. The
// tablet interface itself does not generate events; all events are
// generated by wp_tablet_tool objects when in proximity above a tablet.
//
// A tablet has a number of static characteristics, e.g. device name and
// pid/vid. These capabilities are sent in an event sequence after the
// wp_tablet_seat.tablet_added event. This initial event sequence is
// terminated by a wp_tablet.done event.
type ZwpTabletV2 struct {
	client.BaseProxy
	nameHandler    ZwpTabletV2NameHandlerFunc
	idHandler      ZwpTabletV2IdHandlerFunc
	pathHandler    ZwpTabletV2PathHandlerFunc
	doneHandler    ZwpTabletV2DoneHandlerFunc
	removedHandler ZwpTabletV2RemovedHandlerFunc
}

// NewZwpTabletV2 : graphics tablet device
//
// The wp_tablet interface represents one graphics tablet device. The
// tablet interface itself does not generate events; all events are
// generated by wp_tablet_tool objects when in proximity above a tablet.
//
// A tablet has a number of static characteristics, e.g. device name and
// pid/vid. These capabilities are sent in an event sequence after the
// wp_tablet_seat.tablet_added event. This initial event sequence is
// terminated by a wp_tablet.done event.
func NewZwpTabletV2(ctx *client.Context) *ZwpTabletV2 {
	zwpTabletV2 := &ZwpTabletV2{}
	ctx.Register(zwpTabletV2)
	return zwpTabletV2
}

// Destroy : destroy the tablet object
//
// This destroys the client's resource for this tablet object.
func (i *ZwpTabletV2) Destroy() error {
	defer i.MarkZombie()
	const opcode = 0
	const _reqBufLen = 8
	var _reqBuf [_reqBufLen]byte
	l := 0
	client.PutUint32(_reqBuf[l:4], i.ID())
	l += 4
	client.PutUint32(_reqBuf[l:l+4], uint32(_reqBufLen<<16|opcode&0x0000ffff))
	l += 4
	err := i.Context().WriteMsg(_reqBuf[:], nil)
	return err
}

