// ZwpTabletPadGroupV2ModeSwitchEvent : mode switch event
//
// Notification that the mode was switched.
//
// A mode applies to all buttons, rings and strips in a group
// simultaneously, but a client is not required to assign different actions
// for each mode. For example, a client may have mode-specific button
// mappings but map the ring to vertical scrolling in all modes. Mode
// indices start at 0.
//
// Switching modes is compositor-dependent. The compositor may provide
// visual cues to the client about the mode, e.g. by toggling LEDs on
// the tablet device. Mode-switching may be software-controlled or
// controlled by one or more physical buttons. For example, on a Wacom
// Intuos Pro, the button inside the ring may be assigned to switch
// between modes.
//
// The compositor will also send this event after wp_tablet_pad.enter on
// each group in order to notify of the current mode. Groups that only
// feature one mode will use mode=0 when emitting this event.
//
// If a button action in the new mode differs from the action in the
// previous mode, the client should immediately issue a
// wp_tablet_pad.set_feedback request for each changed button.
//
// If a ring or strip action in the new mode differs from the action
// in the previous mode, the client should immediately issue a
// wp_tablet_ring.set_feedback or wp_tablet_strip.set_feedback request
// for each changed ring or strip.
type ZwpTabletPadGroupV2ModeSwitchEvent struct {
	Time   uint32
	Serial uint32
	Mode   uint32
}
type ZwpTabletPadGroupV2ModeSwitchHandlerFunc func(ZwpTabletPadGroupV2ModeSwitchEvent)

// SetModeSwitchHandler : sets handler for ZwpTabletPadGroupV2ModeSwitchEvent
func (i *ZwpTabletPadGroupV2) SetModeSwitchHandler(f ZwpTabletPadGroupV2ModeSwitchHandlerFunc) {
	i.modeSwitchHandler = f
}

func (i *ZwpTabletPadGroupV2) Dispatch(opcode uint32, fd int, data []byte) {
	switch opcode {
	case 0:
		if i.buttonsHandler == nil {
			return
		}
		var e ZwpTabletPadGroupV2ButtonsEvent
		l := 0
		buttonsLen := int(client.Uint32(data[l : l+4]))
		l += 4
		e.Buttons = make([]byte, buttonsLen)
		copy(e.Buttons, data[l:l+buttonsLen])
		l += buttonsLen

		i.buttonsHandler(e)
	case 1:
		if i.ringHandler == nil {
			return
		}
		var e ZwpTabletPadGroupV2RingEvent
		l := 0
		ringID := client.Uint32(data[l : l+4])
		if ring, ok := i.Context().GetProxy(ringID).(*ZwpTabletPadRingV2); ok && !ring.IsZombie() {
			e.Ring = ring
		} else if ringID != 0 {
			ring := &ZwpTabletPadRingV2{}
			i.Context().RegisterWithID(ring, ringID)
			e.Ring = ring
		}
		l += 4

		i.ringHandler(e)
	case 2:
		if i.stripHandler == nil {
			return
		}
		var e ZwpTabletPadGroupV2StripEvent
		l := 0
		stripID := client.Uint32(data[l : l+4])
		if strip, ok := i.Context().GetProxy(stripID).(*ZwpTabletPadStripV2); ok && !strip.IsZombie() {
			e.Strip = strip
		} else if stripID != 0 {
			strip := &ZwpTabletPadStripV2{}
			i.Context().RegisterWithID(strip, stripID)
			e.Strip = strip
		}
		l += 4

		i.stripHandler(e)
	case 3:
		if i.modesHandler == nil {
			return
		}
		var e ZwpTabletPadGroupV2ModesEvent
		l := 0
		e.Modes = client.Uint32(data[l : l+4])
		l += 4

		i.modesHandler(e)
	case 4:
		if i.doneHandler == nil {
			return
		}
		var e ZwpTabletPadGroupV2DoneEvent

		i.doneHandler(e)
	case 5:
		if i.modeSwitchHandler == nil {
			return
		}
		var e ZwpTabletPadGroupV2ModeSwitchEvent
		l := 0
		e.Time = client.Uint32(data[l : l+4])
		l += 4
		e.Serial = client.Uint32(data[l : l+4])
		l += 4
		e.Mode = client.Uint32(data[l : l+4])
		l += 4

		i.modeSwitchHandler(e)
	default:
		panic("client: unsupported opcode")
	}
}

// ZwpTabletPadV2InterfaceName is the name of the interface as it appears in the [client.Registry].
// It can be used to match the [client.RegistryGlobalEvent.Interface] in the
// [Registry.SetGlobalHandler] and can be used in [Registry.Bind] if this applies.
const ZwpTabletPadV2InterfaceName = "zwp_tablet_pad_v2"

// ZwpTabletPadV2 : a set of buttons, rings and strips
//
// A pad device is a set of buttons, rings and strips
// usually physically present on the tablet device itself. Some
// exceptions exist where the pad device is physically detached, e.g. the
// Wacom ExpressKey Remote.
//
// Pad devices have no axes that control the cursor and are generally
// auxiliary devices to the tool devices used on the tablet surface.
//
// A pad device has a number of static characteristics, e.g. the number
// of rings. These capabilities are sent in an event sequence after the
// wp_tablet_seat.pad_added event before any actual events from this pad.
// This initial event sequence is terminated by a wp_tablet_pad.done
// event.
//
// All pad features (buttons, rings and strips) are logically divided into
// groups and all pads have at least one group. The available groups are
// notified through the wp_tablet_pad.group event; the compositor will
// emit one event per group before emitting wp_tablet_pad.done.
//
// Groups may have multiple modes. Modes allow clients to map multiple
// actions to a single pad feature. Only one mode can be active per group,
// although different groups may have different active modes.
type ZwpTabletPadV2 struct {
	client.BaseProxy
	groupHandler   ZwpTabletPadV2GroupHandlerFunc
	pathHandler    ZwpTabletPadV2PathHandlerFunc
	buttonsHandler ZwpTabletPadV2ButtonsHandlerFunc
	doneHandler    ZwpTabletPadV2DoneHandlerFunc
	buttonHandler  ZwpTabletPadV2ButtonHandlerFunc
	enterHandler   ZwpTabletPadV2EnterHandlerFunc
	leaveHandler   ZwpTabletPadV2LeaveHandlerFunc
	removedHandler ZwpTabletPadV2RemovedHandlerFunc
}

// NewZwpTabletPadV2 : a set of buttons, rings and strips
//
// A pad device is a set of buttons, rings and strips
// usually physically present on the tablet device itself. Some
// exceptions exist where the pad device is physically detached, e.g. the
// Wacom ExpressKey Remote.
//
// Pad devices have no axes that control the cursor and are generally
// auxiliary devices to the tool devices used on the tablet surface.
//
// A pad device has a number of static characteristics, e.g. the number
// of rings. These capabilities are sent in an event sequence after the
// wp_tablet_seat.pad_added event before any actual events from this pad.
// This initial event sequence is terminated by a wp_tablet_pad.done
// event.
//
// All pad features (buttons, rings and strips) are logically divided into
// groups and all pads have at least one group. The available groups are
// notified through the wp_tablet_pad.group event; the compositor will
// emit one event per group before emitting wp_tablet_pad.done.
//
// Groups may have multiple modes. Modes allow clients to map multiple
// actions to a single pad feature. Only one mode can be active per group,
// although different groups may have different active modes.
func NewZwpTabletPadV2(ctx *client.Context) *ZwpTabletPadV2 {
	zwpTabletPadV2 := &ZwpTabletPadV2{}
	ctx.Register(zwpTabletPadV2)
	return zwpTabletPadV2
}

// SetFeedback : set compositor feedback
//
// Requests the compositor to use the provided feedback string
// associated with this button. This request should be issued immediately
// after a wp_tablet_pad_group.mode_switch event from the corresponding
// group is received, or whenever a button is mapped to a different
// action. See wp_tablet_pad_group.mode_switch for more details.
//
// Clients are encouraged to provide context-aware descriptions for
// the actions associated with each button, and compositors may use
// this information to offer visual feedback on the button layout
// (e.g. on-screen displays).
//
// Button indices start at 0. Setting the feedback string on a button
// that is reserved by the compositor (i.e. not belonging to any
// wp_tablet_pad_group) does not generate an error but the compositor
// is free to ignore the request.
//
// The provided string 'description' is a UTF-8 encoded string to be
// associated with this ring, and is considered user-visible; general
// internationalization rules apply.
//
// The serial argument will be that of the last
// wp_tablet_pad_group.mode_switch event received for the group of this
// button. Requests providing other serials than the most recent one will
// be ignored.
//
//	button: button index
//	description: button description
//	serial: serial of the mode switch event
func (i *ZwpTabletPadV2) SetFeedback(button uint32, description string, serial uint32) error {
	const opcode = 0
	descriptionLen := client.PaddedLen(len(description) + 1)
	_reqBufLen := 8 + 4 + (4 + descriptionLen) + 4
	_reqBuf := make([]byte, _reqBufLen)
	l := 0
	client.PutUint32(_reqBuf[l:4], i.ID())
	l += 4
	client.PutUint32(_reqBuf[l:l+4], uint32(_reqBufLen<<16|opcode&0x0000ffff))
	l += 4
	client.PutUint32(_reqBuf[l:l+4], uint32(button))
	l += 4
	client.PutString(_reqBuf[l:l+(4+descriptionLen)], description)
	l += (4 + descriptionLen)
	client.PutUint32(_reqBuf[l:l+4], uint32(serial))
	l += 4
	err := i.Context().WriteMsg(_reqBuf, nil)
	return err
}

// Destroy : destroy the pad object
//
// Destroy the wp_tablet_pad object. Objects created from this object
// are unaffected and should be destroyed separately.
func (i *ZwpTabletPadV2) Destroy() error {
	defer i.MarkZombie()
	const opcode = 1
	const _reqBufLen = 8
	var _reqBuf [_reqBufLen]byte
	l := 0
	client.PutUint32(_reqBuf[l:4], i.ID())
	l += 4
	client.PutUint32(_reqBuf[l:l+4], uint32(_reqBufLen<<16|opcode&0x0000ffff))
	l += 4
	err := i.Context().WriteMsg(_reqBuf[:], nil)
	return err
}

type ZwpTabletPadV2ButtonState uint32

// ZwpTabletPadV2ButtonState : physical button state
//
// Describes the physical state of a button that caused the button
// event.
const (
	// ZwpTabletPadV2ButtonStateReleased : the button is not pressed
	ZwpTabletPadV2ButtonStateReleased ZwpTabletPadV2ButtonState = 0
	// ZwpTabletPadV2ButtonStatePressed : the button is pressed
	ZwpTabletPadV2ButtonStatePressed ZwpTabletPadV2ButtonState = 1
)

func (e ZwpTabletPadV2ButtonState) Name() string {
	switch e {
	case ZwpTabletPadV2ButtonStateReleased:
		return "released"
	case ZwpTabletPadV2ButtonStatePressed:
		return "pressed"
	default:
		return ""
	}
}

func (e ZwpTabletPadV2ButtonState) Value() string {
	switch e {
	case ZwpTabletPadV2ButtonStateReleased:
		return "0"
	case ZwpTabletPadV2ButtonStatePressed:
		return "1"
	default:
		return ""
	}
}

func (e ZwpTabletPadV2ButtonState) String() string {
	return e.Name() + "=" + e.Value()
}

